$path = Join-Path $PSScriptRoot 'src\utils\developerTools.ts'
$content = [IO.File]::ReadAllText($path)
$pattern = "(?s)// HTTP status codes.*?\];\r?\nexport function findStatus"
$data = '100|Continue|Client should continue with the request;101|Switching Protocols|Server is switching protocols per the Upgrade header;102|Processing|Request accepted, processing in progress (WebDAV);103|Early Hints|Server returns some response headers before the final response;200|OK|Request succeeded;201|Created|A new resource was created;202|Accepted|Request accepted for processing, but processing is incomplete;203|Non-Authoritative Information|Returned meta-information is no longer authoritative;204|No Content|Request succeeded with no response body;205|Reset Content|Client should reset the document view;206|Partial Content|Server delivers only part of the resource (Range request);207|Multi-Status|Multiple status codes: used by WebDAV;208|Already Reported|Members of a DAV binding were already enumerated ((WebDAV));226|IM Used|Server fulfilled a GET for an instance manifest;300|Multiple Choices|Resource has multiple representations;301|Moved Permanently|Resource has a permanent new location;302|Found|Temporary redirect;303|See Other|Redirect to another URI using GET;304|Not Modified|Cached response remains valid;305|Use Proxy|Resource must be accessed through a proxy (deprecated);307|Temporary Redirect|Temporary redirect keeping method and body;308|Permanent Redirect|Permanent redirect keeping method and body;400|Bad Request|Malformed request;401|Unauthorized|Authentication is required or invalid;402|Payment Required|Reserved for future payment requirements;403|Forbidden|Server refuses authorization;404|Not Found|Resource does not exist;405|Method Not Allowed|HTTP method is unsupported for this resource;406|Not Acceptable|No representation matches the acceptable content;407|Proxy Authentication Required|Authentication is required via a proxy;408|Request Timeout|Server timed out waiting for the request;409|Conflict|Request conflicts with current state;410|Gone|Resource is no longer available;411|Length Required|Content-Length header is required;412|Precondition Failed|A precondition in the request failed;413|Content Too Large|Request body is too large;414|URI Too Long|Request URI is longer than the server can process;415|Unsupported Media Type|Media type is not supported;416|Range Not Satisfiable|Requested range cannot be satisfied;417|Expectation Failed|Expectation stated in the request failed;418|I''m a Teapot|Server refuses to brew coffee (hypertext coffee pot;421|Misdirected Request|Request was sent to a server unable to respond;422|Unprocessable Content|Request well-formed but semantic validation failed;423|Locked|Resource is locked ((WebDAV));424|Failed Dependency|Request failed due to a previous failure (WebDAV;425|Too Early|Server is unwilling to process an early request;426|Upgrade Required|Client should switch to a different protocol;428|Precondition Required|Server requires conditional request headers;429|Too Many Requests|Rate limit exceeded;431|Request Header Fields Too Large|Request headers are too large;451|Unavailable For Legal Reasons|Resource is unavailable for legal reasons;500|Internal Server Error|Unexpected server error;501|Not Implemented|Server does not support the request method;502|Bad Gateway|Upstream service failed;503|Service Unavailable|Service is unavailable or overloaded;504|Gateway Timeout|Upstream service timed out;505|HTTP Version Not Supported|HTTP version used is not supported;506|Variant Also Negotiates|Server has an internal configuration error in content negotiation;507|Insufficient Storage|Server cannot store the representation (WebDAV;508|Loop Detected|Server detected an infinite loop ((WebDAV));510|Not Extended|Server requires further extensions to fulfill the request;511|Network Authentication Required|Network access authentication is required'
$parts = $data -split ';'
$lines = $parts | ForEach-Object {
  $f = $_ -split '\|'
  '  [{0}, "{1}", "{2}"],' -f $f[0], $f[1], $f[2]
}
$newBlock = @()
$newBlock += '// HTTP status codes (migrated from app/core/http_status.py)'
$newBlock += 'export const STATUS_CODES: Array<[number, string, string]> = ['
$newBlock += $lines
$newBlock += '];'
$newBlock += ''
$newBlock += 'export function findStatus'
$content = [regex]::Replace($content, $pattern, ($newBlock -join "`n"))
[IO.File]::WriteAllText($path, $content, (New-Object System.Text.UTF8Encoding($false)))
Write-Output 'status codes patched'